server.resource(
  "readme",
  "file:///project/README.md",
  {
    description: "The project README, explaining setup and usage",
    mimeType: "text/markdown"
  },
  async (uri) => {
    const text = await fs.readFile("./README.md", "utf-8");
    return {
      contents: [
        { uri: uri.href, mimeType: "text/markdown", text }
      ]
    };
  }
);

@mcp.resource(
    "ticket-stats://support/open-count",
    name="open-ticket-count",
    description="The current count of open support tickets",
    mime_type="application/json"
)
def get_open_ticket_count() -> str:
    count = ticket_db.count(status="open")
    return json.dumps({"open_count": count, "checked_at": now_iso()})

// resources/docs.ts
export function registerDocResources(server) {
  server.resource("readme", "file:///project/README.md", {
    description: "The project README",
    mimeType: "text/markdown"
  }, readReadme);

  server.resource("changelog", "file:///project/CHANGELOG.md", {
    description: "Recent changes to the project",
    mimeType: "text/markdown"
  }, readChangelog);
}

// server.ts
import { registerDocResources } from "./resources/docs";
import { registerTicketResources } from "./resources/tickets";
