// Static: the style guide never changes at runtime
server.resource(
  "style-guide",
  "wiki://team/style-guide",
  { description: "Writing style guide for the team wiki", mimeType: "text/markdown" },
  async (uri) => ({
    contents: [{ uri: uri.href, mimeType: "text/markdown", text: styleGuideText }]
  })
);

// Dynamic: recomputed on every read
server.resource(
  "draft-count",
  "wiki://team/draft-count",
  { description: "Current number of draft articles awaiting review", mimeType: "application/json" },
  async (uri) => ({
    contents: [{
      uri: uri.href,
      mimeType: "application/json",
      text: JSON.stringify({ drafts: wikiDb.countDrafts() })
    }]
  })
);
